inline LocalizedMessage energyAuthorizationPanelMessage(std::string_view language,EnergyAuthorizationPanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=energyAuthorizationPanelMessageKeyCount)return {};
    const auto &source=energyAuthorizationPanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:energyAuthorizationPanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string energyAuthorizationPanelEnglish(EnergyAuthorizationPanelMessageKey key){return std::string(energyAuthorizationPanelMessage("en",key).text);}
